// Adapted from createVariableCollection, createSemanticTokens, and createComponentWithVariants.
const page=figma.currentPage;page.name='S04 · 交互设计与原型';
const created=[];const keep=n=>(created.push(n.id),n);
const regular={family:'Noto Sans SC',style:'Regular'},bold={family:'Noto Sans SC',style:'Bold'};
await figma.loadFontAsync(regular);await figma.loadFontAsync(bold);
const color=h=>({r:parseInt(h.slice(1,3),16)/255,g:parseInt(h.slice(3,5),16)/255,b:parseInt(h.slice(5,7),16)/255});
const collection=figma.variables.createVariableCollection('超级工厂 / 工程浅色');collection.renameMode(collection.defaultModeId,'浅色');
const colors={surface:'#FFFFFF',canvas:'#F2F5F8',ink:'#172D40',muted:'#61778B',line:'#D9E3EA',accent:'#087DA5',tint:'#E6F4F9',success:'#167A61',warning:'#9A610E',error:'#B74242',dark:'#123E55'};
const vars={};for(const [name,hex]of Object.entries(colors)){const primitive=figma.variables.createVariable('primitive/'+name,collection,'COLOR');primitive.scopes=[];primitive.setValueForMode(collection.defaultModeId,{...color(hex),a:1});const v=figma.variables.createVariable('color/'+name,collection,'COLOR');v.scopes=['FRAME_FILL','SHAPE_FILL','TEXT_FILL','STROKE_COLOR'];v.setValueForMode(collection.defaultModeId,{type:'VARIABLE_ALIAS',id:primitive.id});vars[name]=v;}
for(const n of [4,8,12,16,24,32]){const v=figma.variables.createVariable('spacing/'+n,collection,'FLOAT');v.scopes=['GAP','WIDTH_HEIGHT'];v.setValueForMode(collection.defaultModeId,n);vars['spacing'+n]=v;}
const states=figma.variables.createVariableCollection('原型 / 演示状态');states.renameMode(states.defaultModeId,'示例');
const defaults={caseKey:'DEMO-L03',caseTitle:'L03 · 总装检查与包装线',caseFacts:'界面与布局示例 · 八台设备 · 未执行本批模拟',resultSummary:'结果仅作交互演示；本批未执行工具或模拟。',agentBranch:'success',mechanism:'受限折叠容器',paperStage:'成型',paperResult:'Pass 示例 · 非真实专业结果',bindingStatus:'待人工用途确认 · 原型示例',reportFormat:'PDF',feedback:'empty',draftState:'草稿字段未改动',camera:'默认等距',viewTime:'0 s',selection:'装配设备 A01'};
for(const [name,value]of Object.entries(defaults)){const v=figma.variables.createVariable(name,states,'STRING');v.scopes=['TEXT_CONTENT'];v.setValueForMode(states.defaultModeId,value);vars[name]=v;}
const paint=name=>figma.variables.setBoundVariableForPaint({type:'SOLID',color:color(colors[name])},'color',vars[name]);
function txt(parent,s,size=18,strong=false){const n=keep(figma.createText());parent.appendChild(n);n.fontName=strong?bold:regular;n.fontSize=size;n.characters=s;n.fills=[paint('ink')];n.textAutoResize='WIDTH_AND_HEIGHT';return n;}
const comps={};const buttons=[];
for(const [i,kind]of ['主操作','次操作','文字操作'].entries()){const c=keep(figma.createComponent());c.name='类型='+kind;c.resize(200,44);c.layoutMode='HORIZONTAL';c.primaryAxisSizingMode='FIXED';c.counterAxisSizingMode='FIXED';c.primaryAxisAlignItems='CENTER';c.counterAxisAlignItems='CENTER';c.paddingLeft=16;c.paddingRight=16;c.itemSpacing=8;c.cornerRadius=6;c.fills=[paint(kind==='主操作'?'accent':kind==='次操作'?'surface':'tint')];c.strokes=kind==='次操作'?[paint('line')]:[];const t=txt(c,'操作按钮',17,true);t.fills=[paint(kind==='主操作'?'surface':'accent')];const key=c.addComponentProperty('文字','TEXT','操作按钮');t.componentPropertyReferences={characters:key};c.x=i*240;c.y=-1100;buttons.push(c);}
const set=keep(figma.combineAsVariants(buttons,page));set.name='工程 / 操作按钮';set.description='中文工程界面按钮；根据已发现的基础设计库调整为灰白蓝青与 Noto Sans SC。';set.x=0;set.y=-1100;comps.buttonSet=set.id;comps.primary=buttons[0].id;comps.secondary=buttons[1].id;comps.quiet=buttons[2].id;
const field=keep(figma.createComponent());field.name='工程 / 属性字段';field.resize(352,112);field.layoutMode='VERTICAL';field.primaryAxisSizingMode='AUTO';field.counterAxisSizingMode='FIXED';field.paddingTop=12;field.paddingBottom=12;field.paddingLeft=12;field.paddingRight=12;field.itemSpacing=6;field.cornerRadius=6;field.fills=[paint('canvas')];field.x=0;field.y=-850;
for(const [role,value,size,strong]of [['label','字段名称',15,true],['value','示例值',18,false],['hint','单位 / 来源 · 草稿',12,false]]){const t=txt(field,value,size,strong);t.resize(328,t.height);t.textAutoResize='HEIGHT';const key=field.addComponentProperty(role,'TEXT',value);t.componentPropertyReferences={characters:key};if(role==='hint')t.fills=[paint('muted')];}
comps.field=field.id;
const chip=keep(figma.createComponent());chip.name='工程 / 状态标签';chip.resize(180,30);chip.layoutMode='HORIZONTAL';chip.primaryAxisSizingMode='AUTO';chip.counterAxisSizingMode='FIXED';chip.paddingLeft=10;chip.paddingRight=10;chip.primaryAxisAlignItems='CENTER';chip.counterAxisAlignItems='CENTER';chip.cornerRadius=4;chip.fills=[paint('tint')];const ct=txt(chip,'原型示例',13,true);ct.fills=[paint('accent')];const ck=chip.addComponentProperty('文字','TEXT','原型示例');ct.componentPropertyReferences={characters:ck};chip.x=450;chip.y=-850;comps.chip=chip.id;
const assets={};for(const [i,name]of ['line','assembly','robot','robot_back','robot_free','low','robot_closed','robot_open'].entries()){const n=keep(figma.createRectangle());n.name='资产 / '+name;n.resize(960,540);n.x=i*1000;n.y=-2200;n.fills=[paint('canvas')];assets[name]=n.id;}
return {created,components:comps,variables:Object.fromEntries(Object.entries(vars).map(([k,v])=>[k,v.id])),collections:[collection.id,states.id],assets,font:regular};
